-- Arbeitsrecht Berufsbildung > Rechte von Auszubildenden > Anspruch auf Arbeitsmittel Bereitstellung (§ 14 Abs. 1 BBiG)
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Hat ein Fachinformatiker Anspruch auf einen Arbeitscomputer vom Betrieb?', 2, '[{"text": "Ja", "correct": true, "because": "§ 14 Abs. 1 BBiG verpflichtet den Betrieb zur Bereitstellung"}, {"text": "Nein", "correct": false, "because": "Arbeitsmittel sind Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Ausbildungsunternehmen von einem Fachinformatiker verlangen, seine eigene Software zu kaufen?', 2, '[{"text": "Nein", "correct": true, "because": "§ 14 Abs. 1 BBiG schreibt betriebliche Bereitstellung vor"}, {"text": "Ja", "correct": false, "because": "Kosten dürfen nicht auf den Auszubildenden abgewälzt werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein Fachinformatiker selbst für die Reparatur defekter Arbeitsmittel aufkommen?', 2, '[{"text": "Nein", "correct": true, "because": "Der Betrieb ist nach § 14 Abs. 1 BBiG verantwortlich"}, {"text": "Ja", "correct": false, "because": "Reparaturen sind Sache des Betriebs"}]'),
('00000000-0000-0000-0000-000000000000', 'Hat ein Fachinformatiker Anspruch auf aktuelle Arbeitsmittel wie moderne Programmiersoftware?', 2, '[{"text": "Ja", "correct": true, "because": "§ 14 Abs. 1 BBiG fordert zweckmäßige Mittel"}, {"text": "Nein", "correct": false, "because": "Aktualität ist Teil der Angemessenheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Darf ein Betrieb einem Fachinformatiker Arbeitsmittel verweigern, wenn er sie falsch benutzt?', 2, '[{"text": "Nein", "correct": true, "because": "§ 14 Abs. 1 BBiG garantiert die Bereitstellung"}, {"text": "Ja", "correct": false, "because": "Verweigerung ist nicht zulässig"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche gesetzliche Grundlage verpflichtet einen Betrieb, einem Fachinformatiker Arbeitsmittel bereitzustellen?', 2, '[{"text": "§ 14 Abs. 1 BBiG", "correct": true, "because": "Regelt die Bereitstellungspflicht"}, {"text": "§ 13 BBiG", "correct": false, "because": "Bezieht sich auf Ausbildungsqualität"}, {"text": "§ 17 BBiG", "correct": false, "because": "Regelt die Vergütung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was sollte ein Fachinformatiker tun, wenn ihm keine Arbeitsmittel zur Verfügung gestellt werden?', 3, '[{"text": "Den Betrieb und die IHK informieren", "correct": true, "because": "Das ist der rechtliche Weg gemäß § 14 Abs. 1 BBiG"}, {"text": "Selbst Mittel kaufen", "correct": false, "because": "Nicht seine Pflicht"}, {"text": "Die Ausbildung abbrechen", "correct": false, "becauseZu radikal ohne Klärung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Arbeitsmittel muss einem Fachinformatiker zwingend bereitgestellt werden?', 3, '[{"text": "Ein funktionsfähiger Computer", "correct": true, "because": "Notwendig für die Ausbildung gemäß § 14 Abs. 1 BBiG"}, {"text": "Ein privates Smartphone", "correct": false, "because": "Nicht betrieblich erforderlich"}, {"text": "Ein Kaffeeautomat", "correct": false, "because": "Kein Arbeitsmittel"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer ist verantwortlich für die Bereitstellung von Arbeitsmitteln für einen Fachinformatiker?', 2, '[{"text": "Der Ausbildungsbetrieb", "correct": true, "because": "§ 14 Abs. 1 BBiG legt dies fest"}, {"text": "Die Berufsschule", "correct": false, "because": "Schule stellt keine Arbeitsmittel"}, {"text": "Der Auszubildende selbst", "correct": false, "because": "Nicht seine Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert, wenn ein Betrieb einem Fachinformatiker keine Arbeitsmittel bereitstellt?', 3, '[{"text": "Die IHK kann den Betrieb verwarnen", "correct": true, "because": "Verstoß gegen § 14 Abs. 1 BBiG"}, {"text": "Der Auszubildende verliert seinen Anspruch", "correct": false, "because": "Anspruch bleibt bestehen"}, {"text": "Die Berufsschule übernimmt die Kosten", "correct": false, "because": "Schule ist nicht zuständig"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Arbeitsmittel muss ein Betrieb einem Fachinformatiker laut § 14 Abs. 1 BBiG bereitstellen?', 4, '[{"text": "Computer mit Entwicklungsumgebung", "correct": true, "because": "Notwendig für die Ausbildung"}, {"text": "Netzwerkkabel und Tools", "correct": true, "because": "Teil der IT-Ausbildung"}, {"text": "Private Kleidung", "correct": false, "because": "Kein Arbeitsmittel"}, {"text": "Lernsoftware", "correct": true, "because": "Fördert die Ausbildung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen kann ein Fachinformatiker ergreifen, wenn ihm Arbeitsmittel fehlen?', 3, '[{"text": "Den Betrieb darauf hinweisen", "correct": true, "because": "Erster Schritt zur Klärung"}, {"text": "Die IHK informieren", "correct": true, "because": "IHK überwacht die Einhaltung"}, {"text": "Selbst kaufen und abrechnen", "correct": false, "because": "Nicht seine Pflicht"}, {"text": "Die Berufsschule bitten, Mittel zu stellen", "correct": false, "because": "Schule ist nicht verantwortlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Arbeitsmittel sind für die Ausbildung eines Fachinformatikers unerlässlich?', 4, '[{"text": "Hardware wie Computer", "correct": true, "because": "Grundlage der IT-Ausbildung"}, {"text": "Software wie IDEs", "correct": true, "because": "Notwendig für Programmierung"}, {"text": "Küchengeräte", "correct": false, "because": "Keine Arbeitsmittel"}, {"text": "Netzwerkgeräte", "correct": true, "because": "Teil der Ausbildung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenzen drohen einem Betrieb, der keine Arbeitsmittel für einen Fachinformatiker bereitstellt?', 3, '[{"text": "Verwarnung durch die IHK", "correct": true, "because": "IHK überwacht § 14 Abs. 1 BBiG"}, {"text": "Schadensersatzforderungen", "correct": true, "because": "Bei Nachweis möglich"}, {"text": "Automatische Schließung", "correct": false, "because": "Nicht vorgesehen"}, {"text": "Verlust der Ausbildungsberechtigung", "correct": true, "because": "Bei schweren Verstößen möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was darf ein Betrieb nicht vom Fachinformatiker verlangen?', 3, '[{"text": "Eigene Hardware kaufen", "correct": true, "because": "§ 14 Abs. 1 BBiG verbietet das"}, {"text": "Softwarelizenzen bezahlen", "correct": true, "because": "Betrieb muss stellen"}, {"text": "Arbeitsmittel sorgfältig nutzen", "correct": false, "because": "Das ist erlaubt"}, {"text": "Reparaturkosten tragen", "correct": true, "because": "Betrieb ist verantwortlich"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Fachinformatiker hat Anspruch auf aktuelle Arbeitsmittel. b) Der Betrieb darf alte Software verwenden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Aktualität ist Pflicht, b) kann unangemessen sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) § 14 Abs. 1 BBiG verpflichtet den Betrieb zur Bereitstellung. b) Der Fachinformatiker muss Arbeitsmittel mitbringen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Betrieb ist verantwortlich, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Arbeitsmittel umfassen Computer und Software. b) Der Betrieb muss keine Arbeitsmittel warten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wartung ist Pflicht, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Ein Fachinformatiker darf Arbeitsmittel selbst kaufen, wenn der Betrieb sie nicht stellt. b) Der Anspruch gilt auch in der Probezeit.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Kauf ist nicht seine Pflicht"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": true, "because": "Anspruch gilt immer"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Der Betrieb muss Arbeitsmittel für die IHK-Prüfung bereitstellen. b) Arbeitsmittel müssen funktionsfähig sein.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Nicht nur für Prüfung"}, {"text": "Beides stimmt", "correct": true, "because": "Beides ist Teil von § 14 Abs. 1 BBiG"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]');

